#include "client.hpp"
#include "assets.hpp"
#include "item_catalog.hpp"
#include "item_placement.hpp"
#include "pathfinding.hpp"
#include <fstream>
#include <iostream>
#include <thread>
#include <chrono>
#include <sys/stat.h>
#include <unistd.h>
#include <stdexcept>
using namespace mu::client;
void need(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void pumpFor(Session& s,double seconds){auto until=std::chrono::steady_clock::now()+std::chrono::duration<double>(seconds);while(std::chrono::steady_clock::now()<until){s.pump();std::this_thread::sleep_for(std::chrono::milliseconds(25));}}
void openVault(Session& s,const mu::assets::Terrain& terrain){auto state=s.state();auto route=mu::viewer::find_path(terrain.attributes,state.x,state.y,146,113);need(!route.empty()||(state.x==146&&state.y==113),"No route to warehouse");for(std::size_t n=0;n<route.size();n+=14){auto end=std::min(n+14,route.size());std::vector<unsigned> steps(route.begin()+n,route.begin()+end);state=s.movePath(state.x,state.y,steps);pumpFor(s,steps.size()*.52+.25);}pumpFor(s,1);state=s.state();unsigned npc=0;bool found=false;for(auto& pair:state.viewport->entities)if(pair.second.type==240){npc=pair.first;found=true;break;}need(found,"Warehouse NPC not present");s.talk(npc);pumpFor(s,1.5);state=s.state();need(state.npc.result==2&&state.npc.itemsReady&&state.npc.lockState==0,"Warehouse unavailable");}
int main(int argc,char** argv){try{need(argc==2,"Usage: MuClient-transfer-test PRIVATE_CREDENTIALS");struct stat st{};need(stat(argv[1],&st)==0&&st.st_uid==getuid()&&(st.st_mode&077)==0,"Credentials must be owner-only");std::ifstream file(argv[1]);std::string account,password;std::getline(file,account);std::getline(file,password);need(account=="muverify","Only isolated test account permitted");auto profile=load_profile();auto terrain=mu::assets::load_terrain(std::filesystem::path(profile.assetDirectory)/"Data",0);auto catalog=mu::ui::load_item_catalog(std::filesystem::path(profile.assetDirectory)/"Data",profile.language);Item original;unsigned vaultSlot=240,originalVaultSlot=240;bool fromVault=false;
 for(unsigned phase=0;phase<(fromVault?4u:3u);phase++){Session s(profile,0);need(s.login(account,password)==1,"Test account login failed (close GUI session first)");s.select("MuOptions");pumpFor(s,1);auto state=s.state();need(state.inventory&&state.inventory->ready,"Inventory not ready");if(phase==0){if(!state.inventory->items.count(14)){openVault(s,terrain);state=s.state();for(auto& entry:*state.npc.items)if(entry.second.index==2560&&entry.second.level==15){originalVaultSlot=entry.first;break;}need(originalVaultSlot<120,"Test staff absent from both main bag and warehouse");need(s.moveItem({2,originalVaultSlot,0,14}),"Initial withdrawal rejected");fromVault=true;state=s.state();s.closeTalk();pumpFor(s,.5);}original=state.inventory->items.at(14);need(original.index==2560&&original.level==15,"Unexpected fixture item");need(state.money>=2,"Fixture needs at least 2 Zen for withdrawal tax");}else if(phase==1)need(!state.inventory->items.count(14),"Deposit not persisted after relog");else if(phase==2)need(state.inventory->items.at(14).wire==original.wire,"Withdrawal not persisted after relog");else need(!state.inventory->items.count(14),"Final restore left duplicate bag item");openVault(s,terrain);state=s.state();if(phase==0){for(unsigned slot=0;slot<120;slot++)if(mu::ui::can_place_item(*state.npc.items,*catalog,2,slot,original)){vaultSlot=slot;break;}need(vaultSlot<120,"No free warehouse footprint");auto before=state.inventory->items;if(state.inventory->items.count(18))need(!s.moveItem({0,14,0,18}),"Server accepted occupied destination");else need(!s.moveItem({0,14,0,75}),"Server accepted footprint outside bag");need(s.state().inventory->items.at(14).wire==original.wire,"Rejected move changed source");need(s.moveItem({0,14,2,vaultSlot}),"Deposit rejected");need(!s.state().inventory->items.count(14)&&s.state().npc.items->at(vaultSlot).wire==original.wire,"Deposit state mismatch");std::cout<<"Deposit confirmed; warehouse slot="<<vaultSlot<<std::endl;}else if(phase==1){need(state.npc.items->count(vaultSlot)&&state.npc.items->at(vaultSlot).wire==original.wire,"Warehouse item not persisted after relog");need(s.moveItem({2,vaultSlot,0,14}),"Withdrawal rejected (item remains in warehouse)");need(s.state().inventory->items.at(14).wire==original.wire&&!s.state().npc.items->count(vaultSlot),"Withdrawal state mismatch");std::cout<<"Withdrawal confirmed."<<std::endl;}else if(phase==2){need(!state.npc.items->count(vaultSlot),"Duplicated item remained in warehouse");if(fromVault)need(s.moveItem({0,14,2,originalVaultSlot}),"Return to original warehouse slot rejected");}else need(state.npc.items->at(originalVaultSlot).wire==original.wire,"Original warehouse location not restored");s.closeTalk();pumpFor(s,.7);s.disconnect();std::this_thread::sleep_for(std::chrono::seconds(2));}
 std::cout<<"PASS: rejected occupied slot, deposit, relog persistence, withdrawal, second relog; fixture restored to its original location.\n";return 0;}catch(const std::exception& e){std::cerr<<"Transfer test: "<<e.what()<<"\nIf deposit succeeded, the test item remains safely in MuOptions warehouse until withdrawn.\n";return 1;}}
